import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    "m": "http://schemas.openxmlformats.org/officeDocument/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    col = 0
    for ch in m.group(1):
        col = col * 26 + (ord(ch) - ord("A") + 1)
    return col - 1, int(m.group(2)) - 1

def cell_type_map():
    return {0: "numeric", 1: "string", 2: "formula", 3: "blank", 4: "boolean", 5: "error", 6: "inline"}

with zipfile.ZipFile("budget.xlsx") as z:
    print("Archive entries:", [n for n in z.namelist() if "sheet" in n.lower() or "workbook" in n.lower()])

    wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = wb_xml.find("m:sheets", NS)
    sheet_names = [s.get("name") for s in sheets.findall("m:sheet", NS)]
    print("Sheet names:", sheet_names)

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/officeDocument/2006/main}t"))
            shared.append(text)

    # map sheet name -> rId -> file
    rels_xml = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.get("Id"): r.get("Target") for r in rels_xml}

    for sheet_name in sheet_names:
        # find rId for sheet
        rId = None
        for s in sheets.findall("m:sheet", NS):
            if s.get("name") == sheet_name:
                rId = s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_map[rId]
        if not target.startswith("xl/"):
            target = "xl/" + target
        path = target.lstrip("/")
        print(f"\n=== Sheet: {sheet_name} (file={path}) ===")
        sheet_xml = ET.fromstring(z.read(path))
        rows = []
        for row in sheet_xml.iter("{http://schemas.openxmlformats.org/officeDocument/2006/main}row"):
            row_data = {}
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                isel = c.find("m:is", NS)
                col, rnum = col_to_idx(ref)
                val = None
                if t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif t == "inlineStr" and isel is not None:
                    val = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/officeDocument/2006/main}t"))
                elif v is not None:
                    val = v.text
                row_data[col] = val
            if row_data:
                rows.append((int(row.get("r")), row_data))
        max_col = max(max(r[1].keys()) for r in rows) if rows else 0
        for rnum, row_data in sorted(rows):
            line = []
            for c in range(max_col + 1):
                line.append(row_data.get(c, ""))
            print(f"row {rnum}: {line}")

